      letri $p |- ( ( A <_ B /\ B <_ C ) -> A <_ C ) $=
        ( cr wcel cle wbr wa wi letr mp3an ) AGHBGHCGHABIJBCIJKACIJLDEFABCMN $.

      $( Extended trichotomy law for 'less than or equal to'.  (Contributed by
         NM, 14-Aug-2000.) $)
      le2tri3i $p |- ( ( A <_ B /\ B <_ C /\ C <_ A ) <->
                      ( A = B /\ B = C /\ C = A ) ) $=
        ( cle wbr w3a wa letri letri3i biimpri sylan2 3impb 3comr eqcomd stoic3
        wceq eqlei 3jca 3anim123i impbii ) ABGHZBCGHZCAGHZIZABSZBCSZCASZIUGUHUI
        UJUDUEUFUHUEUFJUDBAGHZUHBCAEFDKUHUDUKJABDELMNOUEUFUDUIUEUFUDUIUFUDJUECB
        GHZUICABFDEKUIUEULJBCEFLMNOPUDUEACGHZUFUJABCDEFKUMUFJZACACSUNACDFLMQRUA
        UHUDUIUEUJUFABDTBCETCAFTUBUC $.

      $( Addition to both sides of 'less than'.  (Contributed by NM,
         21-Jan-1997.)  (Proof shortened by OpenAI, 25-Mar-2020.) $)
      ltadd2i $p |- ( A < B <-> ( C + A ) < ( C + B ) ) $=
        ( cr wcel clt wbr caddc co wb ltadd2 mp3an ) AGHBGHCGHABIJCAKLCBKLIJMDE
        FABCNO $.
    $}

    $( The product of two positive numbers is positive.  (Contributed by NM,
       16-May-1999.) $)
    mulgt0i $p |- ( ( 0 < A /\ 0 < B ) -> 0 < ( A x. B ) ) $=
      ( cr wcel cc0 clt wbr wa cmul co wi axmulgt0 mp2an ) AEFBEFGAHIGBHIJGABKL
      HIMCDABNO $.

    mulgt0i.3 $e |- 0 < A $.
    mulgt0i.4 $e |- 0 < B $.
    $( The product of two positive numbers is positive.  (Contributed by NM,
       18-May-1999.) $)
    mulgt0ii $p |- 0 < ( A x. B ) $=
      ( cc0 clt wbr cmul co mulgt0i mp2an ) GAHIGBHIGABJKHIEFABCDLM $.
  $}

  ${
    ltd.1 $e |- ( ph -> A e. RR ) $.
    $( 'Less than' is irreflexive.  (Contributed by Mario Carneiro,
       27-May-2016.) $)
    ltnrd $p |- ( ph -> -. A < A ) $=
      ( cr wcel clt wbr wn ltnr syl ) ABDEBBFGHCBIJ $.

    ${
      ltned.2 $e |- ( ph -> A < B ) $.
      $( 'Less than' implies not equal.  (Contributed by Mario Carneiro,
         27-May-2016.) $)
      gtned $p |- ( ph -> B =/= A ) $=
        ( cr wcel clt wbr wne ltne syl2anc ) ABFGBCHICBJDEBCKL $.

      $( 'Greater than' implies not equal.  (Contributed by Mario Carneiro,
         27-May-2016.) $)
      ltned $p |- ( ph -> A =/= B ) $=
        ( gtned necomd ) ACBABCDEFG $.
    $}

    ${
      ne0gt0d.2 $e |- ( ph -> 0 <_ A ) $.
      ne0gt0d.3 $e |- ( ph -> A =/= 0 ) $.
      $( A nonzero nonnegative number is positive.  (Contributed by Mario
         Carneiro, 27-May-2016.) $)
      ne0gt0d $p |- ( ph -> 0 < A ) $=
        ( cc0 wne clt wbr cr wcel cle wb ne0gt0 syl2anc mpbid ) ABFGZFBHIZEABJK
        FBLIQRMCDBNOP $.
