    divmul $p |- ( ( A e. CC /\ B e. CC /\ ( C e. CC /\ C =/= 0 ) )
                 -> ( ( A / C ) = B <-> ( C x. B ) = A ) ) $=
      ( vx cc wcel cc0 wne wa w3a cdiv co wceq cv cmul crio divval 3expb eqeq1d
      3adant2 wreu wb simp2 receu oveq2 riota2 3imp3i2an bitr4d ) AEFZBEFZCEFZC
      GHZIZJZACKLZBMCDNZOLZAMZDEPZBMZCBOLZAMZUNUOUSBUIUMUOUSMZUJUIUKULVCDACQRTS
      UIUJUMUJURDEUAZVBUTUBUIUJUMUCUIUKULVDDACUDRURVBDEBUPBMUQVAAUPBCOUESUFUGUH
      $.
  $}

