  $( An integer is its own floor.  (Contributed by NM, 15-Nov-2004.) $)
  flid $p |- ( A e. ZZ -> ( |_ ` A ) = A ) $=
    ( cz wcel cfl cfv wceq cle wbr cr zre flle syl leidd wb flge mpancom reflcl
    mpbid letri3d mpbir2and ) ABCZADEZAFUBAGHZAUBGHZUAAICZUCAJZAKLUAAAGHZUDUAAU
    FMUEUAUGUDNUFAAOPRUAUBAUAUEUBICUFAQLUFST $.

  $( The floor function is idempotent.  (Contributed by NM, 17-Aug-2008.) $)
  flidm $p |- ( A e. RR -> ( |_ ` ( |_ ` A ) ) = ( |_ ` A ) ) $=
    ( cr wcel cfl cfv cz wceq flcl flid syl ) ABCADEZFCKDEKGAHKIJ $.

  $( A real number equals its floor iff it is an integer.  (Contributed by NM,
     11-Nov-2008.) $)
  flidz $p |- ( A e. RR -> ( ( |_ ` A ) = A <-> A e. ZZ ) ) $=
    ( cr wcel cfl cfv wceq cz flcl eleq1 syl5ibcom flid impbid1 ) ABCZADEZAFZAG
    CZMNGCOPAHNAGIJAKL $.

  $( The floor of a non-integer real is less than it.  (Contributed by Glauco
     Siliprandi, 11-Dec-2019.) $)
  flltnz $p |- ( ( A e. RR /\ -. A e. ZZ ) -> ( |_ ` A ) < A ) $=
    ( cr cz wn wa cfl cfv reflcl adantr simpl cle wbr c1 caddc co fllelt simpld
    wcel clt wceq simpr wb flidz mtbird neqned necomd leneltd ) ABRZACRZDZEZAFG
    ZAUHULBRUJAHIUHUJJUKULAKLZAULMNOSLZUHUMUNEUJAPIQUKULAUKULAUKULATZUIUHUJUAUH
    UOUIUBUJAUCIUDUEUFUG $.

  $( Ordering relation for the floor function.  (Contributed by NM,
     31-Dec-2005.)  (Proof shortened by Fan Zheng, 14-Jul-2016.) $)
  flwordi $p |- ( ( A e. RR /\ B e. RR /\ A <_ B ) ->
                 ( |_ ` A ) <_ ( |_ ` B ) ) $=
    ( cr wcel cle wbr w3a cfl cfv simp1 flcld zred simp2 flle simp3 letrd cz wb
    syl flge syl2anc mpbid ) ACDZBCDZABEFZGZAHIZBEFZUGBHIEFZUFUGABUFUGUFAUCUDUE
    JZKZLUJUCUDUEMZUFUCUGAEFUJANSUCUDUEOPUFUDUGQDUHUIRULUKBUGTUAUB $.

  $( Ordering relation for the floor function.  (Contributed by Mario Carneiro,
     7-Jun-2016.) $)
  flword2 $p |- ( ( A e. RR /\ B e. RR /\ A <_ B ) ->
                 ( |_ ` B ) e. ( ZZ>= ` ( |_ ` A ) ) ) $=
    ( cr wcel cle wbr w3a cfl cfv cuz simp1 flcld simp2 flwordi eluz2 syl3anbrc
    cz ) ACDZBCDZABEFZGZAHIZQDBHIZQDUBUCEFUCUBJIDUAARSTKLUABRSTMLABNUBUCOP $.

  ${
    $d x y z A $.  $d x y B $.
