    cshfn $p |- ( ( W e. { f | E. l e. NN0 f Fn ( 0 ..^ l ) } /\ N e. ZZ )
                  -> ( W cyclShift N ) = if ( W = (/) , (/) ,
                           ( ( W substr <. ( N mod ( # ` W ) ) , ( # ` W ) >. )
                             ++ ( W prefix ( N mod ( # ` W ) ) ) ) ) ) $=
      ( vw vn cv co c0 wceq cfv cmo cop csubstr cpfx cconcat cif adantr oveq12d
      chash cc0 cfzo wfn cn0 wrex cz ccsh wa wb eqeq1 simpl simpr fveq2 opeq12d
      cab ifbieq2d df-csh 0ex ovex ifex ovmpoa ) EFCBAGUADGUBHUCDUDUEAUOUFEGZIJ
