$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Longer string literals
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)
  $( Syntax for the length 2 word constructor. $)
  cs2 $a class <" A B "> $.

  $( Syntax for the length 3 word constructor. $)
  cs3 $a class <" A B C "> $.

  $( Syntax for the length 4 word constructor. $)
  cs4 $a class <" A B C D "> $.

  $( Syntax for the length 5 word constructor. $)
  cs5 $a class <" A B C D E "> $.

  $( Syntax for the length 6 word constructor. $)
  cs6 $a class <" A B C D E F "> $.

  $( Syntax for the length 7 word constructor. $)
  cs7 $a class <" A B C D E F G "> $.

  $( Syntax for the length 8 word constructor. $)
  cs8 $a class <" A B C D E F G H "> $.

  $( Define the length 2 word constructor.  (Contributed by Mario Carneiro,
     26-Feb-2016.) $)
  df-s2 $a |- <" A B "> = ( <" A "> ++ <" B "> ) $.

  $( Define the length 3 word constructor.  (Contributed by Mario Carneiro,
     26-Feb-2016.) $)
  df-s3 $a |- <" A B C "> = ( <" A B "> ++ <" C "> ) $.

  $( Define the length 4 word constructor.  (Contributed by Mario Carneiro,
     26-Feb-2016.) $)
  df-s4 $a |- <" A B C D "> = ( <" A B C "> ++ <" D "> ) $.

  $( Define the length 5 word constructor.  (Contributed by Mario Carneiro,
     26-Feb-2016.) $)
  df-s5 $a |- <" A B C D E "> = ( <" A B C D "> ++ <" E "> ) $.

  $( Define the length 6 word constructor.  (Contributed by Mario Carneiro,
     26-Feb-2016.) $)
  df-s6 $a |- <" A B C D E F "> = ( <" A B C D E "> ++ <" F "> ) $.

  $( Define the length 7 word constructor.  (Contributed by Mario Carneiro,
     26-Feb-2016.) $)
  df-s7 $a |- <" A B C D E F G "> = ( <" A B C D E F "> ++ <" G "> ) $.

  $( Define the length 8 word constructor.  (Contributed by Mario Carneiro,
     26-Feb-2016.) $)
  df-s8 $a |- <" A B C D E F G H "> = ( <" A B C D E F G "> ++ <" H "> ) $.

  ${
    cats1cld.1 $e |- T = ( S ++ <" X "> ) $.
    ${
      cats1cld.2 $e |- ( ph -> S e. Word A ) $.
      cats1cld.3 $e |- ( ph -> X e. A ) $.
      $( Closure of concatenation with a singleton word.  (Contributed by Mario
         Carneiro, 26-Feb-2016.) $)
      cats1cld $p |- ( ph -> T e. Word A ) $=
        ( cs1 cconcat co cword wcel s1cld ccatcl syl2anc eqeltrid ) ADCEIZJKZBL
        ZFACTMRTMSTMGAEBHNBCROPQ $.

      cats1co.4 $e |- ( ph -> F : A --> B ) $.
      cats1co.5 $e |- ( ph -> ( F o. S ) = U ) $.
      cats1co.6 $e |- V = ( U ++ <" ( F ` X ) "> ) $.
      $( Closure of concatenation with a singleton word.  (Contributed by Mario
         Carneiro, 26-Feb-2016.) $)
      cats1co $p |- ( ph -> ( F o. T ) = V ) $=
        ( cs1 cconcat co ccom wcel cfv cword wf wceq s1cld syl3anc s1co syl2anc
        ccatco oveq12d eqtrd coeq2i 3eqtr4g ) AGDIPZQRZSZFIGUAPZQRZGESHAUPGDSZG
        UNSZQRZURADBUBZTUNVBTBCGUCZUPVAUDKAIBLUEMBCDUNGUIUFAUSFUTUQQNAIBTVCUTUQ
        UDLMBCIGUGUHUJUKEUOGJULOUM $.
    $}

    ${
      cats1cli.2 $e |- S e. Word _V $.
      $( Closure of concatenation with a singleton word.  (Contributed by Mario
         Carneiro, 26-Feb-2016.) $)
      cats1cli $p |- T e. Word _V $=
        ( cs1 cconcat co cvv cword wcel s1cli ccatcl mp2an eqeltri ) BACFZGHZIJ
        ZDARKPRKQRKECLIAPMNO $.

      cats1fvn.3 $e |- ( # ` S ) = M $.
      $( The last symbol of a concatenation with a singleton word.
         (Contributed by Mario Carneiro, 26-Feb-2016.) $)
      cats1fvn $p |- ( X e. V -> ( T ` M ) = X ) $=
        ( wcel cfv cc0 cs1 chash caddc co cconcat oveq2i cn0 cvv cn cword lencl
        ax-mp eqeltrri nn0cni addlidi eqtr2i fveq12i cfzo wceq s1cli c1 eqeltri
        s1len 1nn lbfzo0 mpbir ccatval3 mp3an eqtri s1fv eqtrid ) EDICBJZKELZJZ
        EVCKAMJZNOZAVDPOZJZVECVGBVHFVGKCNOCVFCKNHQCCVFCRHASUAZIZVFRIGSAUBUCUDUE
        UFUGUHVKVDVJIKKVDMJZUIOIZVIVEUJGEUKVMVLTIVLULTEUNUOUMVLUPUQSAVDKURUSUTE
        DVAVB $.

      ${
        cats1fv.4 $e |- ( Y e. V -> ( S ` N ) = Y ) $.
        cats1fv.5 $e |- N e. NN0 $.
        cats1fv.6 $e |- N < M $.
        $( A symbol other than the last in a concatenation with a singleton
           word.  (Contributed by Mario Carneiro, 26-Feb-2016.) $)
        cats1fv $p |- ( Y e. V -> ( T ` N ) = Y ) $=
          ( wcel cfv co cvv cc0 clt cn0 cs1 cconcat cword chash cfzo wceq s1cli
          fveq1i cuz wbr nn0uz eleqtri lencl nn0z mp2b breqtrri elfzo2 mpbir3an
          cz ccatval1 mp3an eqtri eqtrid ) GENDBOZDAOZGVDDAFUAZUBPZOZVEDBVGHUHA
          QUCZNZVFVINDRAUDOZUEPNZVHVEUFIFUGVLDRUIOZNVKUSNZDVKSUJDTVMLUKULVJVKTN
          VNIQAUMVKUNUODCVKSMJUPDRVKUQURQQAVFDUTVAVBKVC $.
      $}

      cats1len.4 $e |- ( M + 1 ) = N $.
      $( The length of concatenation with a singleton word.  (Contributed by
         Mario Carneiro, 26-Feb-2016.) $)
      cats1len $p |- ( # ` T ) = N $=
        ( chash cfv cs1 cconcat co fveq2i c1 caddc cvv wcel eqtri cword ccatlen
        wceq s1cli mp2an s1len oveq12i ) BJKAELZMNZJKZDBUIJFOUJCPQNZDUJAJKZUHJK
        ZQNZUKARUAZSUHUOSUJUNUCGEUDRRAUHUBUEULCUMPQHEUFUGTITT $.
    $}

    ${
      cats1cat.2 $e |- A e. Word _V $.
      cats1cat.3 $e |- S e. Word _V $.
      cats1cat.4 $e |- C = ( B ++ <" X "> ) $.
      cats1cat.5 $e |- B = ( A ++ S ) $.
      $( Closure of concatenation with a singleton word.  (Contributed by Mario
         Carneiro, 26-Feb-2016.) $)
      cats1cat $p |- C = ( A ++ T ) $=
        ( cs1 cconcat co oveq1i cvv cword wcel wceq s1cli ccatass mp3an 3eqtr4i
        eqtri oveq2i ) BFLZMNZADUFMNZMNZCAEMNUGADMNZUFMNZUIBUJUFMKOAPQZRDULRUFU
        LRUKUISHIFTPADUFUAUBUDJEUHAMGUEUC $.
    $}
  $}

  ${
    cats2cat.b $e |- B e. Word _V $.
    cats2cat.d $e |- D e. Word _V $.
    cats2cat.a $e |- A = ( B ++ <" X "> ) $.
    cats2cat.c $e |- C = ( <" Y "> ++ D ) $.
    $( Closure of concatenation of concatenations with singleton words.
       (Contributed by AV, 1-Mar-2021.) $)
    cats2cat $p |- ( A ++ C ) = ( ( B ++ <" X Y "> ) ++ D ) $=
      ( cconcat co cs1 cs2 cvv wcel wceq s1cli ccatass mp3an cword ccatcl mp2an
      oveq12i df-s2 eqcomi oveq2i eqtri oveq1i 3eqtr2i ) ACKLBEMZKLZFMZDKLZKLZU
      LUMKLZDKLZBEFNZKLZDKLAULCUNKIJUDULOUAZPZUMUTPZDUTPUQUOQBUTPZUKUTPZVAGERZO
      BUKUBUCFRZHOULUMDSTUPUSDKUPBUKUMKLZKLZUSVCVDVBUPVHQGVEVFOBUKUMSTVGURBKURV
      GEFUEUFUGUHUIUJ $.
  $}

  ${
    s2eqd.1 $e |- ( ph -> A = N ) $.
    s2eqd.2 $e |- ( ph -> B = O ) $.
    $( Equality theorem for a doubleton word.  (Contributed by Mario Carneiro,
       27-Feb-2016.) $)
    s2eqd $p |- ( ph -> <" A B "> = <" N O "> ) $=
      ( cs1 cconcat co cs2 s1eqd oveq12d df-s2 3eqtr4g ) ABHZCHZIJDHZEHZIJBCKDE
      KAPRQSIABDFLACEGLMBCNDENO $.

    s3eqd.3 $e |- ( ph -> C = P ) $.
    $( Equality theorem for a length 3 word.  (Contributed by Mario Carneiro,
       27-Feb-2016.) $)
    s3eqd $p |- ( ph -> <" A B C "> = <" N O P "> ) $=
      ( cs2 cs1 cconcat co cs3 s2eqd s1eqd oveq12d df-s3 3eqtr4g ) ABCKZDLZMNFG
      KZELZMNBCDOFGEOAUAUCUBUDMABCFGHIPADEJQRBCDSFGEST $.

    s4eqd.4 $e |- ( ph -> D = Q ) $.
    $( Equality theorem for a length 4 word.  (Contributed by Mario Carneiro,
       27-Feb-2016.) $)
    s4eqd $p |- ( ph -> <" A B C D "> = <" N O P Q "> ) $=
      ( cs3 cs1 cconcat co cs4 s3eqd df-s4 s1eqd oveq12d 3eqtr4g ) ABCDNZEOZPQH
      IFNZGOZPQBCDERHIFGRAUDUFUEUGPABCDFHIJKLSAEGMUAUBBCDETHIFGTUC $.

    s5eqd.5 $e |- ( ph -> E = R ) $.
    $( Equality theorem for a length 5 word.  (Contributed by Mario Carneiro,
       27-Feb-2016.) $)
