$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Signum (sgn or sign) function
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $c sgn $. $( Signum function, often written "sgn" or "sign". $)

  $( Extend class notation to include the Signum function. $)
  csgn $a class sgn $.

  $( Signum function.  We do not call it "sign", which is homophonic with
     "sine" ( ~ df-sin ).  Defined as "sgn" in ISO 80000-2:2009(E) operation
     2-9.13.  It is named "sign" (with the same definition) in the "NIST
     Digital Library of Mathematical Functions" , front introduction, "Common
     Notations and Definitions" section at
     ~ http://dlmf.nist.gov/front/introduction#Sx4 .  We define this over
     ` RR* ` ( ~ df-xr ) instead of ` RR ` so that it can accept ` +oo ` and
     ` -oo ` .  Note that ~ df-psgn defines the sign of a permutation, which is
     different.  Value shown in ~ sgnval .  (Contributed by David A. Wheeler,
     15-May-2015.) $)
  df-sgn $a |- sgn = ( x e. RR* |-> if ( x = 0 , 0 ,
                                         if ( x < 0 , -u 1 , 1 ) ) ) $.

  ${
    $d x A $.
    $( Value of the signum function.  (Contributed by David A. Wheeler,
       15-May-2015.) $)
    sgnval $p |- ( A e. RR* -> ( sgn ` A ) =
                             if ( A = 0 , 0 , if ( A < 0 , -u 1 , 1 ) ) ) $=
      ( vx cv cc0 wceq clt wbr c1 cneg cif cxr csgn eqeq1 breq1 ifbieq2d df-sgn
      ifbid c0ex negex ifex 1ex fvmpt ) BABCZDEZDUCDFGZHIZHJZJADEZDADFGZUFHJZJK
      LUCAEZUDUHUGUJDUCADMUKUEUIUFHUCADFNQOBPUHDUJRUIUFHHSUATTUB $.
  $}

  $( The signum of 0 is 0.  (Contributed by David A. Wheeler, 15-May-2015.) $)
  sgn0 $p |- ( sgn ` 0 ) = 0 $=
    ( cc0 csgn cfv wceq clt wbr cneg cif cxr wcel 0xr sgnval ax-mp eqid iftruei
    c1 eqtri ) ABCZAADZAAAEFPGPHZHZAAIJRUADKALMSATANOQ $.

  $( The signum of a positive extended real is 1.  (Contributed by David A.
     Wheeler, 15-May-2015.) $)
  sgnp $p |- ( ( A e. RR* /\ 0 < A ) -> ( sgn ` A ) = 1 ) $=
    ( cxr wcel cc0 clt wbr wa csgn cfv wceq c1 cif sgnval adantr wne 0xr xrltne
    cneg mp3an1 iffalsed neneqd wn wi xrltnsym mpan imp 3eqtrd ) ABCZDAEFZGZAHI
    ZADJZDADEFZKRZKLZLZUOKUHUKUPJUIAMNUJULDUOUJADDBCZUHUIADOPDAQSUATUJUMUNKUHUI
    UMUBZUQUHUIURUCPDAUDUEUFTUG $.

  $( The signum of a positive real is 1.  (Contributed by David A. Wheeler,
     18-May-2015.) $)
  sgnrrp $p |- ( A e. RR+ -> ( sgn ` A ) = 1 ) $=
    ( crp wcel cxr cc0 clt wbr csgn cfv c1 wceq rpxr rpgt0 sgnp syl2anc ) ABCAD
    CEAFGAHIJKALAMANO $.

  $( The signum of 1 is 1.  (Contributed by David A. Wheeler, 26-Jun-2016.) $)
  sgn1 $p |- ( sgn ` 1 ) = 1 $=
    ( c1 cxr wcel cc0 clt wbr csgn cfv wceq 1xr 0lt1 sgnp mp2an ) ABCDAEFAGHAIJ
    KALM $.

  $( The signum of ` +oo ` is 1.  (Contributed by David A. Wheeler,
     26-Jun-2016.) $)
  sgnpnf $p |- ( sgn ` +oo ) = 1 $=
    ( cpnf cxr wcel cc0 clt wbr csgn cfv c1 wceq pnfxr 0ltpnf sgnp mp2an ) ABCD
    AEFAGHIJKLAMN $.

  $( The signum of a negative extended real is -1.  (Contributed by David A.
     Wheeler, 15-May-2015.) $)
  sgnn $p |- ( ( A e. RR* /\ A < 0 ) -> ( sgn ` A ) = -u 1 ) $=
    ( cxr wcel cc0 clt wbr wa csgn cfv wceq c1 cneg cif sgnval adantr wn xrltne
    wne 0xr mp3an2 nesym sylib iffalsed iftrue adantl 3eqtrd ) ABCZADEFZGZAHIZA
    DJZDUHKLZKMZMZUMULUGUJUNJUHANOUIUKDUMUIDARZUKPUGDBCUHUOSADQTDAUAUBUCUHUMULJ
    UGUHULKUDUEUF $.

  $( The signum of ` -oo ` is -1.  (Contributed by David A. Wheeler,
     26-Jun-2016.) $)
  sgnmnf $p |- ( sgn ` -oo ) = -u 1 $=
    ( cmnf cxr wcel cc0 clt wbr csgn cfv c1 cneg wceq mnfxr mnflt0 sgnn mp2an )
    ABCADEFAGHIJKLMANO $.

  $( The domain of the signum function.  (Contributed by AV, 16-Jun-2026.) $)
  sgndm $p |- dom sgn = RR* $=
    ( vx cxr cv cc0 wceq clt wbr c1 cneg cif csgn c0ex negex ifex df-sgn dmmpti
    1ex ) ABACZDEZDRDFGZHIZHJZJKSDUBLTUAHHMQNNAOP $.

  $( Closure of the signum:  The signum of an extended real is either -1 or 0
     or 1.  (Contributed by Thierry Arnoux, 28-Sep-2018.) $)
  sgncl $p |- ( A e. RR* -> ( sgn ` A ) e. { -u 1 , 0 , 1 } ) $=
    ( cxr wcel csgn cfv c1 cneg cc0 ctp wceq wa simpr fveq2d sgn0 c0ex eqeltrdi
    eqtrdi clt wbr adantlr tpid2 wne sgnn negex tpid1 1ex tpid3 wo 0xr xrlttri2
    sgnp biimpa mpanl2 mpjaodan pm2.61dane ) ABCZADEZFGZHFIZCZAHUPAHJZKZUQHUSVB
    UQHDEHVBAHDUPVALMNQURHFOUAPUPAHUBZKAHRSZUTHARSZUPVDUTVCUPVDKUQURUSAUCURHFFU
    DUEPTUPVEUTVCUPVEKUQFUSAUKURHFUFUGPTUPHBCZVCVDVEUHZUIUPVFKVCVGAHUJULUMUNUO
    $.

  $( The range of the signum function.  (Contributed by AV, 16-Jun-2026.)
     (Proof shortened by TA, 21-Jun-2026.) $)
  sgnrn $p |- ran sgn = { -u 1 , 0 , 1 } $=
    ( vx csgn crn c1 cneg cc0 ctp cxr wfn cfv wcel wral wss wceq cif mp2an cmnf
    cv fnfvelrn eqeltrri clt wbr df-sgn fnmpt sgncl eqeltrrd mprg rgen fnfvrnss
    sgnval sgnmnf mnfxr sgn0 0xr sgn1 1xr tpssi mp3an eqssi ) BCZDEZFDGZBHIZARZ
    BJZVBKZAHLUTVBMVDFNFVDFUAUBVADOOZVBKVCAHAHVGBVBAUCUDVDHKVEVGVBVDUJVDUEZUFUG
    ZVFAHVHUHAHVBBUIPVAUTKFUTKDUTKVBUTMQBJZVAUTUKVCQHKVJUTKVIULHQBSPTFBJZFUTUMV
    CFHKVKUTKVIUNHFBSPTDBJZDUTUOVCDHKVLUTKVIUPHDBSPTVAFDUTUQURUS $.

  $( The signum function as onto function.  (Contributed by AV,
     16-Jun-2026.) $)
  sgnfo $p |- sgn : RR* -onto-> { -u 1 , 0 , 1 } $=
    ( vx cxr c1 cneg cc0 ctp csgn wfo wfn crn wceq wfun cdm clt wbr cif funmpt2
    cv df-sgn mpbir2an sgndm df-fn sgnrn df-fo ) BCDZECFZGHGBIZGJUFKUGGLGMBKABA
    RZEKEUHENOUECPPGASQUAGBUBTUCBUFGUDT $.

  $( Negation of the signum.  (Contributed by Thierry Arnoux, 1-Oct-2018.) $)
  sgnneg $p |- ( A e. RR -> ( sgn ` -u A ) = -u ( sgn ` A ) ) $=
    ( cr wcel cneg cc0 wceq clt wbr c1 cif csgn cfv wa wn biimpa wb adantr cmin
    cxr co recn negeq0d bicomd eqidd necon3bbid lt0neg2 wo 0red lttri2d ltnsym2
    wne id mpdan jca pm5.17 sylib con2bid bitr3d ifbid eqtrdi syldan ifbieq12d2
    ifnot renegcl rexr sgnval 3syl df-neg a1i syl oveq2d ovif2 biid 0m0e0 caddc
    0cn ax-1cn subnegi 0p1e1 eqtr2i ifbieq12i eqtr4i eqtri 3eqtrd 3eqtr4d ) ABC
    ZADZEFZEWGEGHZIDZIJZJZAEFZEAEGHZIWJJZJZWGKLZAKLZDZWFWHWMEWKEWOWFWMWHWFAAUAU
    BUCZWFWHMEUDWFWHNZAEUKZWKWOFWFXAXBWFWHAEWTUEOWFXBMZWKWNNZWJIJWOXCWIXDWJIXCE
